// Data of the «Proyectos KiCad» views, generated by contenido/proyectos_kicad.py into public/proyectos/
// (see ESQUEMA.md, «Proyectos KiCad»). Board geometry is in hundredths of a millimetre («u»), origin at the
// top-left corner of the board outline, y down (KiCad's frame); polylines are delta coded.

import type { CapaHoja } from '../consolas/datos';

export interface Comprobacion {
  tipo: 'ok' | 'aviso' | 'error';
  texto: string;
  detalle?: string[];
}

export interface PlacaResumen {
  id: string;
  titulo: string;
  ancho: number;
  alto: number;
  capas: number;
  componentes: number;
  redes: number;
  pads: number;
  vias: number;
  pistas: number;
  bytes: number;
  tensiones: number;
  avisos: number;
}

export interface NetlistLibro {
  id: string;
  titulo: string;
  ref: string | null;
  analisis: string[];
  estado?: string;
}

export interface Proyecto {
  id: string;
  titulo: string;
  resumen: string;
  parte: string;
  capitulo: string;
  capitulo_titulo: string;
  color: string;
  figura: string;
  carpeta: string;
  placas: PlacaResumen[];
  netlists: NetlistLibro[];
  netlists_proyecto: string[];
}

export interface Errata {
  placa: string;
  texto: string;
  detalle?: string[];
}

export interface IndiceProyectos {
  version: number;
  proyectos: Proyecto[];
  erratas: Errata[];
  bytes: number;
}

/** 3D model descriptor from the pipeline (proyectos_kicad_pcb.model_for): kind + parameters, mm. */
export interface DescriptorModelo {
  tipo: string;
  /** Fabrication outline box, footprint-local (mm, KiCad axes). */
  caja: [number, number, number, number];
  [k: string]: unknown;
}

export interface Huella {
  r: string;
  v: string;
  /** Footprint name and library. */
  l: string;
  lib: string;
  x: number;
  y: number;
  /** Rotation, degrees counter-clockwise on screen. */
  a: number;
  lado: 'F' | 'B';
  t: 'tht' | 'smd' | 'mec';
  /** [first pad index, count]. */
  pads: [number, number];
  m: DescriptorModelo;
  /** Fabrication outline (local u): ['l', x0, y0, x1, y1 …] polylines, ['p', …] filled, ['c', cx, cy, r]. */
  fab: (string | number)[][];
  /** Function (Spanish) and where it comes from. */
  f: string;
  fo: 'readme' | 'deducida';
  /** Book label of the section that explains it. */
  fr?: string;
  /** Schematic block (column heading). */
  b?: string;
  mpn?: string;
  dnp?: boolean;
  desc?: string;
}

/** [footprint, number, shape c|r|o|rr|t|x, x, y, w, h, rot°, roundrect ratio, drill w, drill h, flags, net, pin function]. */
export type Pad = [number, string, string, number, number, number, number, number, number, number, number, number, number, string];

export const PAD_F = 1;
export const PAD_B = 2;
export const PAD_PTH = 4;
export const PAD_NPTH = 8;
export const PAD_MASK_F = 16;
export const PAD_MASK_B = 32;

export interface Tension {
  v: number;
  origen: 'anotacion' | 'simulacion';
  texto?: string;
}

export interface Red {
  n: string;
  /** Number of pads. */
  p: number;
  v?: Tension;
}

export interface Zona {
  l: 'F' | 'B';
  r: number;
  p: number[];
}

export interface Area {
  capas: string[];
  nombre: string;
  reglas: Record<string, string>;
  p: number[];
}

export interface Serigrafia {
  /** [width mm, n, x0, y0, dx, dy …, n, x0, y0 …] per stroke width. */
  lineas: number[][];
  rellenos: number[][];
  circulos: [number, number, number, number][];
}

export interface DatosPlaca {
  version: number;
  id: string;
  proyecto: string;
  titulo: string;
  proyecto_titulo: string;
  parte: string;
  figura: string | null;
  archivo: string;
  placa: {
    ancho: number;
    alto: number;
    origen: [number, number];
    grosor: number;
    capas: string[];
    cobre_um: number;
    mascara: string;
    mascara_fuente: string;
    serigrafia: string;
    acabado: string | null;
    fabricacion: string;
    contorno: number[];
    apilado: string;
  };
  redes: Red[];
  huellas: Huella[];
  pads: Pad[];
  /** Per copper side: [net, width, x1, y1, x2, y2] repeated. */
  pistas: Record<string, number[]>;
  /** [net, x, y, diameter, drill] repeated. */
  vias: number[];
  zonas: Zona[];
  areas: Area[];
  serigrafia: Record<string, Serigrafia>;
  esquema: { hoja: string; ancho: number; alto: number; notas: string[]; bloques: { nombre: string; refs: string[] }[] };
  simulacion: { titulo: string; fuente: string } | null;
  comprobaciones: Comprobacion[];
}

const cache = new Map<string, Promise<unknown>>();

function pedir<T>(ruta: string, binario = false): Promise<T> {
  let p = cache.get(ruta);
  if (!p) {
    p = fetch(ruta).then((r) => {
      if (!r.ok) throw new Error(`No se pudo cargar ${ruta} (${r.status})`);
      return binario ? r.arrayBuffer() : r.json();
    });
    p.catch(() => cache.delete(ruta));
    cache.set(ruta, p);
  }
  return p as Promise<T>;
}

export function cargarIndice(): Promise<IndiceProyectos> {
  return pedir<IndiceProyectos>('proyectos/indice.json');
}

export function cargarPlaca(id: string): Promise<DatosPlaca> {
  return pedir<DatosPlaca>(`proyectos/${id}.json`);
}

export function cargarCapaEsquema(d: DatosPlaca): Promise<CapaHoja> {
  return pedir<CapaHoja>(`proyectos/${d.esquema.hoja}.json`);
}

export function cargarDibujoEsquema(d: DatosPlaca): Promise<ArrayBuffer> {
  return pedir<ArrayBuffer>(`proyectos/${d.esquema.hoja}.bin`, true);
}

// ------------------------------------------------------------------ geometry helpers

/** Delta-coded polyline → absolute [x, y] pairs (flat). */
export function decodificar(d: number[]): Float64Array {
  const out = new Float64Array(d.length);
  let x = 0;
  let y = 0;
  for (let i = 0; i < d.length; i += 2) {
    x = i === 0 ? d[0]! : x + d[i]!;
    y = i === 0 ? d[1]! : y + d[i + 1]!;
    out[i] = x;
    out[i + 1] = y;
  }
  return out;
}

/** Footprint-local point (u, KiCad axes) → board point. */
export function aPlaca(h: Huella, x: number, y: number): [number, number] {
  const a = (h.a * Math.PI) / 180;
  const c = Math.cos(a);
  const s = Math.sin(a);
  return [h.x + x * c + y * s, h.y - x * s + y * c];
}

/** Board-space box of a footprint's body (fabrication outline), as four corners. */
export function esquinasHuella(h: Huella): [number, number][] {
  const [x0, y0, x1, y1] = h.m.caja.map((v) => v * 100) as [number, number, number, number];
  return [aPlaca(h, x0, y0), aPlaca(h, x1, y0), aPlaca(h, x1, y1), aPlaca(h, x0, y1)];
}

// ------------------------------------------------------------------ names and numbers

const SI: [number, string][] = [
  [1e9, 'G'],
  [1e6, 'M'],
  [1e3, 'k'],
  [1, ''],
  [1e-3, 'm'],
  [1e-6, 'µ'],
  [1e-9, 'n'],
  [1e-12, 'p'],
];

/** «4,70 V», «−34,4 V», «11,2 mV» (decimal comma, U+202F before the unit). */
export function formatoTension(v: number): string {
  if (v === 0) return '0 V';
  const a = Math.abs(v);
  let [f, p] = SI[3]!;
  for (const [ff, pp] of SI) {
    if (a >= ff * 0.9995) {
      f = ff;
      p = pp;
      break;
    }
  }
  const n = v / f;
  const dec = Math.abs(n) >= 100 ? 1 : Math.abs(n) >= 10 ? 2 : 3;
  const t = n.toFixed(dec).replace(/\.?0+$/, '').replace('.', ',').replace('-', '−');
  return `${t} ${p}V`;
}

export function mm(u: number, dec = 2): string {
  return (u / 100).toFixed(dec).replace(/\.?0+$/, '').replace('.', ',');
}

